30	 * is the only thing re-read here; a failed re-read rejects rather than serving
31	 * a half-gated page.
32	 *
33	 * The strip index maps an id to a LIST of entries, not one: an exact-id read
34	 * expands the requested ids through `resolved_ids`, whose run arm and
35	 * supersede-walk arm can each claim the same event under a different (and
36	 * deliberately non-colliding) chain key, so the join emits that event twice and
37	 * `buildContentItems` parses a SEPARATE payload object for each row. Keying one
38	 * entry per id would restore only the last copy and leave the rest stripped.
39	 */
40	export async function hydrateToolInvocationRequests(opts: {
41	  sql: DbClient;
42	  items: ContentItem[];
43	  organizationId: string;
44	  userId: string | null;
45	  memberRole: string | null;
46	  restoreRequests: boolean;
47	}): Promise<void> {
48	  const { sql, items, organizationId, userId, memberRole, restoreRequests } = opts;
49	  const isAdmin = isAdminOrOwnerRole(memberRole);
50	  const stripped = new Map<
51	    number,
52	    Array<{ payload: Record<string, unknown>; fields: Record<string, unknown> }>
53	  >();
54	
55	  for (const item of items) {
56	    if (item.semantic_type !== AUDIT_SEMANTIC_TYPE || item.origin_type !== 'tool_invocation')
57	      continue;
58	    const payload = item.payload_data as Record<string, unknown> | null | undefined;
59	    if (!payload) continue;
60	    const fields: Record<string, unknown> = {};
61	    for (const key of AUDIT_REQUEST_KEYS) {
62	      if (payload[key] === undefined) continue;
63	      fields[key] = payload[key];
64	      delete payload[key];
65	    }
66	    if (Object.keys(fields).length === 0) continue;
67	    const id = Number(item.id);
68	    const entries = stripped.get(id) ?? [];
69	    entries.push({ payload, fields });
70	    stripped.set(id, entries);
71	  }
