	it("opens the peek with the plural run_ids param the parser accepts", async () => {
		const { container } = await renderCard({
			run_id: 42,
		} as Partial<ContentItem>);

		const card = container.querySelector('[role="button"]');
		expect(card).not.toBeNull();
		fireEvent.click(card as Element);

		expect(openSpy).toHaveBeenCalledTimes(1);
		// `run_ids`, not `run_id`. The singular form parses to null, which silently
		// makes the whole feature unreachable.
		expect(openSpy.mock.calls[0][0]).toMatchObject({
			href: "/acme/activity?run_ids=42",
			runId: 42,
		});
	});

	it("is inert for an event with no run, rather than a button that does nothing", async () => {
		const { container } = await renderCard();

		// No run → no peek destination → the card must not advertise itself as a
		// control. The old bug was the inverse: role="button" with a dead handler.
		expect(container.querySelector('[role="button"]')).toBeNull();
		expect(openSpy).not.toHaveBeenCalled();
	});

	it("ignores clicks that came from a control inside the card", async () => {
		const { container } = await renderCard({
			run_id: 42,
		} as Partial<ContentItem>);

		// "View original" is a real anchor nested inside the clickable card.
		const nested = container.querySelector(
