			payload_type: "empty",
			payload_data: {
				tool_name: "query_sdk",
				request: { query: "real historical value", limit: 1 },
			},
			metadata: { tool_name: "query_sdk" },
		});

		fireEvent.click(screen.getByRole("button", { name: /^request$/i }));

		expect(screen.getByText(/real historical value/)).toBeInTheDocument();
		expect(fetchSpy).not.toHaveBeenCalled();
	});

	it("explains when an audit request exceeded the event storage limit", async () => {
		await renderCard({
			id: 101,
			semantic_type: "audit",
			origin_type: "tool_invocation",
			payload_type: "empty",
			payload_data: {
				tool_name: "run_sdk",
				request_status: "too_large",
				request_bytes: 307_200,
			},
			metadata: { tool_name: "run_sdk" },
		});

		fireEvent.click(screen.getByRole("button", { name: /^request$/i }));

		expect(screen.getByText(/too large to retain/i)).toBeInTheDocument();
		expect(screen.getByText(/307,200 bytes/i)).toBeInTheDocument();
	});
});

