/** Deep-link target for one conversation/session: the org Activity stream
 *  scoped to this client group + activity. The events stream renders the
 *  conversation's run_sdk/query calls and everything else it produced. */
export function clientActivitySearch(
	clientIds: string[],
	activityId?: string,
): Record<string, string> {
	const search: Record<string, string> = {
		client_ids: clientIds.join(","),
	};
	if (activityId) search.mcp_activity_id = activityId;
	return search;
}

export function conversationScopeLabel(scope: ClientActivityScopeItem): string {
	const title = scope.title?.trim();
	if (title) return title;
	// Untitled conversations are identified by their registration — several can
	// coexist for one app, and "Untitled" x N tells them apart by nothing.
	if (scope.activityKind === "session") return "MCP session";
	return scope.clientId;
}

/**
 * A connected app's conversations/sessions, one row each — the same shape
