						<TableHead className="px-3 py-1.5 text-xs">Last action</TableHead>
						<TableHead className="px-3 py-1.5 text-xs">Last active</TableHead>
						<TableHead className="w-8 px-3 py-1.5" />
					</TableRow>
				</TableHeader>
				<TableBody>
					{scopes.map((scope) => {
						return (
							<TableRow
								key={`${scope.clientId}:${scope.activityId}`}
								className="cursor-pointer transition-colors hover:bg-accent/50"
