							>
								<TableCell className="max-w-0 truncate px-3 py-2 text-xs font-medium">
									<Link
										to="/$owner/activity"
										params={{ owner: ownerSlug }}
										search={clientActivitySearch(clientIds, scope.activityId)}
										onClick={(event) => event.stopPropagation()}
										className="hover:underline"
									>
										{conversationScopeLabel(scope)}
									</Link>
									{scope.unreadNotificationCount > 0 ? (
										<Badge variant="secondary" className="ml-2 text-[10px]">
